<?php
/** Phase 7C database tests (ISOLATED test database only): migration, numbering (incl. parallel), milestones, decisions, conversion, printable quotation, permissions. */
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
ob_start(); $root = dirname(__DIR__); require_once $root . '/helpers.php'; require_once $root . '/mailer.php'; require_once $root . '/crm_dashboard.php'; require_once $root . '/crm_views.php'; ob_end_clean();
$pass = 0; $fail = 0; function ok($c, string $m): void { global $pass, $fail; if ($c) $pass++; else { $fail++; fwrite(STDERR, "  FAIL: $m\n"); } } function section(string $t): void { fwrite(STDERR, "== $t\n"); }
if (stripos((string)sec_setting('AIHUB_DB_NAME', 'db.name'), 'test') === false) { fwrite(STDERR, "Refusing: database name must contain 'test'\n"); exit(2); }
db_connection_available(); $pdo = crm_pdo();
$VAL = gmdate('Y-m-d', time() + 20 * 86400);
$mkIn = fn(array $x = []) => $x + ['currency' => 'EUR', 'discount' => '10', 'tax' => '19', 'tax_label' => 'VAT', 'billing_period' => 'one_off', 'valid_until' => $VAL, 'terms' => 'INTERNAL-ONLY-NOTE', 'intro' => 'Thank you for your enquiry.', 'customer_terms' => 'Payment within 14 days.', 'items' => [['description' => 'AI assistant build', 'qty' => '2', 'unit' => '1500.00', 'discount' => '']], 'milestones' => [['label' => 'Deposit', 'pct' => '30', 'due_kind' => 'on_acceptance'], ['label' => 'Delivery', 'pct' => '70', 'due_kind' => 'days_after_acceptance', 'due_days' => '14']]];
if (($argv[1] ?? '') === 'worker') { $u = crm_user_get($pdo, (int)$argv[3]); $o = []; for ($i = 0; $i < (int)$argv[2]; $i++) { [$k, $id] = crm_proposal_create($pdo, $u, (int)$argv[4], $mkIn()); $o[] = $k ? crm_proposal_get($pdo, (int)$id)['number'] : 'ERR:' . $id; } echo implode(',', $o); exit(0); }
function stmts(string $file): array { $b = ''; $o = []; foreach (preg_split('/\R/', (string)file_get_contents($file)) as $l) { $t = trim($l); if ($b === '' && ($t === '' || str_starts_with($t, '--'))) continue; $b .= $l . "\n"; if (str_ends_with($t, ';')) { $o[] = $b; $b = ''; } } return $o; }
function run(PDO $p, string $f): void { foreach (stmts($f) as $s) $p->exec($s); } function tbls(PDO $p): array { return $p->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN); }
foreach (['crm_quote_counter', 'crm_proposal_events', 'crm_proposal_milestones', 'crm_proposal_extra'] as $t) $pdo->exec("DROP TABLE IF EXISTS $t");
foreach (['crm_audit_log', 'crm_activities', 'crm_tasks', 'crm_revenue_entries', 'crm_contracts', 'crm_proposal_items', 'crm_proposal_versions', 'crm_proposals', 'crm_opportunity_stage_history', 'crm_opportunities', 'crm_leads', 'crm_contacts', 'crm_companies', 'crm_users'] as $t) { try { $pdo->exec("DELETE FROM $t"); } catch (Throwable $e) {} }
$H = password_hash('test-only-password', PASSWORD_DEFAULT); [, $o1] = crm_user_create($pdo, 'owner1', 'Olivia Owner', 'owner', $H); [, $s1] = crm_user_create($pdo, 'sales1', 'Sam Sales', 'sales', $H); [, $v1] = crm_user_create($pdo, 'viewer1', 'Vera Viewer', 'viewer', $H);
$owner = crm_user_get($pdo, (int)$o1); $sales = crm_user_get($pdo, (int)$s1); $viewer = crm_user_get($pdo, (int)$v1);
[, $lead] = crm_lead_ingest($pdo, ['kind' => 'development', 'name' => 'Dana Customer', 'email' => 'dana@acme-corp.example', 'company' => '<script>alert(1)</script> GmbH', 'website' => 'https://acme-corp.example', 'message' => 'x', 'budget' => '20k-50k', 'timeline' => 'asap', 'source' => 'test']);
$L = crm_lead_get($pdo, (int)$lead); $newOpp = fn(string $t = 'Opp') => (int)crm_opp_create($pdo, $owner, (int)$L['company_id'], (int)$L['contact_id'], 'development', $t, '5000', 'EUR', null, null, 'negotiation')[1];
$opp = $newOpp();
$mkP = function (array $in = [], ?int $o = null) use ($pdo, $owner, $mkIn, $opp) { [$k, $id] = crm_proposal_create($pdo, $owner, $o ?? $opp, $mkIn($in)); return $k ? (int)$id : 0; };
$approve = function (int $id) use ($pdo, $owner) { crm_proposal_set_status($pdo, $owner, $id, 'pending_approval'); return crm_proposal_set_status($pdo, $owner, $id, 'approved'); };

section('before the migration: Phase 6 behaviour is unchanged');
ok(!crm_quote_ready($pdo), 'tables absent => not ready'); $p0 = $mkP(); $g0 = crm_proposal_get($pdo, $p0); ok($p0 > 0 && preg_match('/^P-\d{4}-\d{4}$/', $g0['number']) === 1, 'proposal created with the old P- number (' . ($g0['number'] ?? '') . ')'); ok((int)$g0['total_minor'] === 321300, 'totals unchanged: 2 x 1,500.00, -10%, +19% = 3,213.00');
ok(crm_quote_mark_sent($pdo, $owner, $p0, gmdate('Y-m-d'), 'email')[1] === 'not_migrated' && crm_quote_record_decision($pdo, $owner, $p0, 'accepted', gmdate('Y-m-d'), 'email')[1] === 'not_migrated', 'new records report not_migrated'); ok(crm_quote_milestones($pdo, (int)$g0['version_id']) === [] && crm_quote_events($pdo, $p0) === [], 'readers return empty');
$html0 = crm_quote_print_html($pdo, $p0); ok($html0 !== null && str_contains($html0, 'Quotation ' . $g0['number']) && str_contains($html0, 'DRAFT - NOT APPROVED'), 'printable quotation works before the migration and stamps drafts');
$approve($p0); crm_proposal_set_status($pdo, $owner, $p0, 'accepted'); ok(crm_quote_convert($pdo, $owner, $p0, '', null, null)[0] === true, 'conversion works before the migration (one-off, start = today)');

section('migration: additive, idempotent, reversible');
$before = tbls($pdo); $sum = []; foreach ($before as $t) $sum[$t] = $pdo->query("CHECKSUM TABLE `$t`")->fetch(PDO::FETCH_NUM)[1];
run($pdo, "$root/database/phase7c_quotations.sql"); run($pdo, "$root/database/phase7c_quotations.sql"); $new = array_values(array_diff(tbls($pdo), $before)); sort($new); ok($new === ['crm_proposal_events', 'crm_proposal_extra', 'crm_proposal_milestones', 'crm_quote_counter'], 'adds exactly four tables');
$same = true; foreach ($before as $t) if ($pdo->query("CHECKSUM TABLE `$t`")->fetch(PDO::FETCH_NUM)[1] !== $sum[$t]) $same = false; ok($same, 'no existing table changed');
run($pdo, "$root/database/phase7c_rollback.sql"); ok(array_values(array_diff(tbls($pdo), $before)) === [], 'rollback removes only the new tables'); run($pdo, "$root/database/phase7c_quotations.sql"); ok(crm_quote_ready($pdo), 're-applies after rollback');

section('automatic numbering');
$a = $mkP(); $b = $mkP(); $na = crm_proposal_get($pdo, $a)['number']; $nb = crm_proposal_get($pdo, $b)['number']; $y = gmdate('Y');
ok($na === "Q-$y-0001" && $nb === "Q-$y-0002", "sequential per year ($na, $nb)"); ok(crm_quote_next_number($pdo, 2031) === 'Q-2031-0001' && crm_quote_next_number($pdo, 2031) === 'Q-2031-0002' && crm_quote_next_number($pdo, 2032) === 'Q-2032-0001', 'each year restarts at 0001');
putenv('AIHUB_QUOTE_PREFIX=ang'); ok(crm_quote_next_number($pdo, 2040) === 'ANG-2040-0001', 'prefix configurable'); putenv('AIHUB_QUOTE_PREFIX');
$cnt0 = (int)$pdo->query("SELECT last_seq FROM crm_quote_counter WHERE year_no=$y")->fetchColumn(); [$bad] = crm_proposal_create($pdo, $owner, $opp, $mkIn(['milestones' => [['label' => 'A', 'pct' => '50']]])); ok(!$bad, 'a proposal with invalid milestones is refused'); ok((int)$pdo->query("SELECT last_seq FROM crm_quote_counter WHERE year_no=$y")->fetchColumn() === $cnt0, 'a failed creation does not burn a number (rolled back)'); ok((int)$pdo->query("SELECT COUNT(*) FROM crm_proposals WHERE number LIKE 'Q-%'")->fetchColumn() === 2, 'and leaves no half-created proposal');
$procs = []; $env = array_merge(getenv(), []); for ($i = 0; $i < 6; $i++) { $procs[$i] = proc_open([PHP_BINARY, __FILE__, 'worker', '5', (string)$owner['id'], (string)$opp], [0 => ['file', '/dev/null', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']], $pp, $root, $env); $pipes[$i] = $pp; }
$nums = []; foreach ($procs as $i => $pr) { $nums = array_merge($nums, explode(',', trim((string)stream_get_contents($pipes[$i][1])))); fclose($pipes[$i][1]); fclose($pipes[$i][2]); proc_close($pr); }
$seqs = array_map(fn($n) => (int)substr($n, -4), $nums); sort($seqs); ok(count($nums) === 30 && count(array_unique($nums)) === 30 && !array_filter($nums, fn($n) => str_starts_with($n, 'ERR')), '30 proposals from 6 parallel processes: all numbers unique'); ok($seqs === range(3, 32), 'and gap-free (3..32)');

section('tax label, milestones, versions');
$q = $mkP(); $g = crm_proposal_get($pdo, $q); $ms = crm_quote_milestones($pdo, (int)$g['version_id']); $ex = crm_quote_extra($pdo, (int)$g['version_id']);
ok(count($ms) === 2 && (int)$ms[0]['amount_minor'] === 96390 && (int)$ms[1]['amount_minor'] === 224910 && $ms[0]['amount_minor'] + $ms[1]['amount_minor'] === (int)$g['total_minor'], 'milestones 30/70 of 3,213.00 = 963.90 + 2,249.10'); ok($ex['tax_label'] === 'VAT' && $ex['intro'] === 'Thank you for your enquiry.' && $ex['customer_terms'] === 'Payment within 14 days.', 'tax label, intro and customer terms stored');
[$ok2, $v2] = crm_proposal_revise($pdo, $owner, $q, $mkIn(['discount' => '0', 'milestones' => [['label' => 'Full', 'pct' => '100', 'due_kind' => 'on_delivery']], 'tax_label' => 'Reverse charge', 'tax' => '0'])); $g2 = crm_proposal_get($pdo, $q);
ok($ok2 && (int)$g2['current_version'] === 2 && (int)$g2['total_minor'] === 300000, 'revision creates version 2 (3,000.00, no tax)'); ok(count(crm_quote_milestones($pdo, (int)$g2['version_id'])) === 1 && crm_quote_extra($pdo, (int)$g2['version_id'])['tax_label'] === 'Reverse charge', 'new version has its own milestones and label'); ok(count(crm_quote_milestones($pdo, (int)$g['version_id'])) === 2, 'version 1 keeps its milestones');
ok(crm_proposal_create($pdo, $viewer, $opp, $mkIn())[1] === 'forbidden', 'a viewer cannot create');
$po = crm_handle_action($pdo, $owner, ['act' => 'proposal_create', 'opp' => (string)$opp, 'currency' => 'EUR', 'discount' => '', 'tax' => '3', 'tax_preset' => '1', 'tax_label' => 'ignored', 'billing_period' => 'one_off', 'valid_until' => $VAL, 'terms' => '', 'item' => [['description' => 'x', 'qty' => '1', 'unit' => '100']], 'ms' => [['label' => 'All', 'pct' => '100']]]);
ok(str_starts_with($po[0], 'v=proposal'), 'form action creates a proposal'); parse_str($po[0], $pq); $gp = crm_proposal_get($pdo, (int)$pq['id']); ok((int)$gp['tax_bp'] === 700 && crm_quote_extra($pdo, (int)$gp['version_id'])['tax_label'] === 'VAT 7%', 'tax preset 1 (VAT 7%) overrides the typed value');

section('printable quotation');
putenv('AIHUB_QUOTE_NAME=Test Seller GmbH'); putenv('AIHUB_QUOTE_ADDRESS=Example Street 1;70173 Stuttgart'); putenv('AIHUB_QUOTE_VAT_ID=DE000000000'); putenv('AIHUB_QUOTE_BANK=IBAN on request');
$draft = crm_quote_print_html($pdo, $q); ok(str_contains($draft, 'DRAFT - NOT APPROVED'), 'a draft is stamped'); ok(str_contains($draft, 'Test Seller GmbH') && str_contains($draft, 'Example Street 1') && str_contains($draft, 'DE000000000') && str_contains($draft, 'IBAN on request'), 'configured seller details are printed');
ok(!str_contains($draft, 'INTERNAL-ONLY-NOTE'), 'internal notes are never printed'); ok(str_contains($draft, 'Thank you for your enquiry.') && str_contains($draft, 'Payment within 14 days.') && str_contains($draft, 'Payment schedule') && str_contains($draft, 'Reverse charge'), 'intro, terms, schedule and tax label appear');
ok(!str_contains($draft, '<script>alert(1)') && str_contains($draft, '&lt;script&gt;alert(1)&lt;/script&gt; GmbH'), 'customer name is escaped'); ok(str_contains($draft, 'Quotation ' . $g['number']) && str_contains($draft, '3,000.00 EUR'), 'number and total shown');
putenv('AIHUB_QUOTE_NAME'); putenv('AIHUB_QUOTE_ADDRESS'); putenv('AIHUB_QUOTE_VAT_ID'); putenv('AIHUB_QUOTE_BANK'); $plain = crm_quote_print_html($pdo, $q); ok(!str_contains($plain, 'VAT ID') && !str_contains($plain, 'Payment details'), 'unconfigured details are left out, not invented'); ok(crm_quote_print_html($pdo, 999999) === null, 'unknown id -> null');
$approve($q); $appr = crm_quote_print_html($pdo, $q); ok(!str_contains($appr, 'class="stamp"'), 'an approved quotation has no stamp'); $pdo->exec("UPDATE crm_proposal_versions SET valid_until='" . gmdate('Y-m-d', time() - 86400) . "' WHERE proposal_id=$q"); ok(str_contains(crm_quote_print_html($pdo, $q), 'VALIDITY ENDED'), 'an approved quotation past its validity date is stamped'); $pdo->exec("UPDATE crm_proposal_versions SET valid_until='$VAL' WHERE proposal_id=$q");

section('sent, accepted, declined');
$d = $mkP(); ok(crm_quote_mark_sent($pdo, $owner, $d, gmdate('Y-m-d'), 'email')[1] === 'send_needs_approved', 'cannot be marked sent before approval'); $approve($d);
ok(crm_quote_mark_sent($pdo, $viewer, $d, gmdate('Y-m-d'), 'email')[1] === 'forbidden', 'viewer cannot record'); ok(crm_quote_mark_sent($pdo, $sales, $d, gmdate('Y-m-d', time() + 86400), 'email')[1] === 'date_invalid', 'future date refused'); ok(crm_quote_mark_sent($pdo, $sales, $d, gmdate('Y-m-d'), 'pigeon')[1] === 'channel_invalid', 'unknown channel refused');
ok(crm_quote_mark_sent($pdo, $sales, $d, gmdate('Y-m-d'), 'email', 'Dana Customer')[0] === true, 'sales can record "sent"'); ok(crm_quote_record_decision($pdo, $sales, $d, 'accepted', gmdate('Y-m-d'), 'email')[1] === 'forbidden', 'sales cannot record the customer decision (revenue permission)');
ok(crm_quote_record_decision($pdo, $owner, $d, 'maybe', gmdate('Y-m-d'), 'email')[1] === 'decision_invalid', 'invalid decision'); ok(crm_quote_record_decision($pdo, $owner, $d, 'declined', gmdate('Y-m-d'), 'email')[1] === 'reason_required', 'declining needs a reason'); ok(crm_quote_record_decision($pdo, $owner, $d, 'accepted', gmdate('Y-m-d', time() + 86400), 'email')[1] === 'date_invalid', 'future decision date refused');
$pdo->exec("UPDATE crm_proposals SET created_at='" . crm_now(time() - 10 * 86400) . "' WHERE id=$d"); $pdo->exec("UPDATE crm_proposal_versions SET valid_until='" . gmdate('Y-m-d', time() - 3 * 86400) . "' WHERE proposal_id=$d");
ok(crm_quote_record_decision($pdo, $owner, $d, 'accepted', gmdate('Y-m-d'), 'email')[1] === 'decision_after_validity', 'acceptance dated after the validity date is refused'); ok(crm_quote_record_decision($pdo, $owner, $d, 'accepted', gmdate('Y-m-d', time() - 5 * 86400), 'email', 'Dana', 'signed-quote.pdf')[0] === true, 'acceptance dated within the validity period is recorded (late entry)');
ok(crm_proposal_get($pdo, $d)['status'] === 'accepted', 'status is accepted'); $ev = crm_quote_events($pdo, $d); ok(count($ev) === 2 && $ev[0]['kind'] === 'sent' && $ev[1]['kind'] === 'accepted' && $ev[1]['reference'] === 'signed-quote.pdf' && $ev[1]['who'] === 'Olivia Owner', 'sent and accepted events with who, when, how, reference'); ok(crm_quote_record_decision($pdo, $owner, $d, 'declined', gmdate('Y-m-d'), 'email', '', '', 'late')[1] === 'transition_invalid', 'a decision cannot be recorded twice');
$e = $mkP(); $approve($e); ok(crm_quote_record_decision($pdo, $owner, $e, 'declined', gmdate('Y-m-d'), 'call', 'Dana', '', 'Budget cut')[0] === true && crm_proposal_get($pdo, $e)['status'] === 'declined', 'decline recorded with reason'); ok(crm_quote_events($pdo, $e)[0]['reason'] === 'Budget cut', 'reason stored');
$pdo->exec("UPDATE crm_proposals SET status='draft' WHERE id=$e"); ok(count(crm_quote_events($pdo, $e)) === 1, 'history is kept');

section('conversion to a contract');
$d2 = crm_proposal_get($pdo, $d); ok(crm_quote_convert($pdo, $sales, $d, '', null, null)[1] === 'forbidden', 'sales cannot convert'); $unacc = $mkP(); ok(crm_quote_convert($pdo, $owner, $unacc, '', null, null)[1] === 'proposal_not_accepted', 'only an accepted proposal converts');
[$okc, $cid] = crm_quote_convert($pdo, $owner, $d, '', null, null); $K = $okc ? crm_contract_get($pdo, (int)$cid) : null; ok($okc && $K['status'] === 'draft' && (int)$K['amount_minor'] === (int)$d2['total_minor'] && $K['start_date'] === gmdate('Y-m-d', time() - 5 * 86400), 'draft contract with the proposal total and the acceptance date as start (draft is not revenue)');
ok(crm_quote_convert($pdo, $owner, $d, '', null, null)[1] === 'already_converted' && (int)$pdo->query("SELECT COUNT(*) FROM crm_contracts WHERE proposal_id=$d")->fetchColumn() === 1, 'exactly one contract per proposal');
ok(in_array((string)$pdo->query('SELECT stage FROM crm_opportunities WHERE id=' . (int)$d2['opportunity_id'])->fetchColumn(), ['won'], true), 'the opportunity moved to won'); ok((int)$pdo->query("SELECT COUNT(*) FROM crm_audit_log WHERE action='proposal_convert'")->fetchColumn() >= 1, 'conversion is audited');
$rec = crm_proposal_get($pdo, $mkP(['billing_period' => 'monthly'], $newOpp('Retainer'))); $approve((int)$rec['id']); crm_quote_record_decision($pdo, $owner, (int)$rec['id'], 'accepted', gmdate('Y-m-d'), 'email'); ok(crm_quote_convert($pdo, $owner, (int)$rec['id'], '', null, null)[1] === 'term_required', 'a recurring proposal still needs a term (existing rule kept)');
$ha = crm_handle_action($pdo, $owner, ['act' => 'contract_create', 'id' => (string)$rec['id'], 'start' => '', 'end' => gmdate('Y-m-d', time() + 365 * 86400), 'renewal' => '']); ok(str_starts_with($ha[0], 'v=contract') && $ha[1] === 'ok', 'the form action converts with a term');

section('views render');
ob_start(); crm_render_view($pdo, $owner, 'proposal', ['id' => (string)$d]); $vh = ob_get_clean(); ok(str_contains($vh, 'Open printable quotation') && str_contains($vh, 'Accepted by customer') && str_contains($vh, 'signed-quote.pdf') && str_contains($vh, 'Contract:'), 'accepted proposal page: print link, event history, contract link');
ob_start(); crm_render_view($pdo, $owner, 'proposal', ['id' => (string)$q]); $vq = ob_get_clean(); ok(str_contains($vq, 'Record: sent to the customer') && str_contains($vq, 'Record: customer decision') && str_contains($vq, 'Payment milestones') && !str_contains($vq, '<option value="accepted">Accepted by customer'), 'approved proposal page: record forms, milestones, no bare accepted/declined status option');
ob_start(); crm_render_view($pdo, $sales, 'proposal', ['id' => (string)$q]); $vs = ob_get_clean(); ok(str_contains($vs, 'Record: sent to the customer') && !str_contains($vs, 'Record: customer decision'), 'sales sees "sent" but not the decision form');
ob_start(); crm_render_view($pdo, $owner, 'contract', ['id' => (string)$cid]); $vc = ob_get_clean(); ok(str_contains($vc, 'Contract #'), 'contract page renders'); ob_start(); crm_render_view($pdo, $owner, 'proposals', []); $vl = ob_get_clean(); ok(str_contains($vl, 'Validity'), 'list has a validity column');
echo "crm_quote_db_test: $pass passed, $fail failed\n"; fwrite(STDERR, "\ncrm_quote_db_test: $pass passed, $fail failed\n"); exit($fail ? 1 : 0);
